<?php
require __DIR__.'/bootstrap.php';$user=aw_need_user(true);$err='';$ok='';$allowed=['masuk','proses','revisi','selesai','ditolak'];
if($_SERVER['REQUEST_METHOD']==='POST')try{aw_check();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if(!$id||!in_array($status,$allowed,true))throw new RuntimeException('Status tidak valid.');$db=aw_db();$db->beginTransaction();$st=$db->prepare('SELECT status FROM aw_applications WHERE id=? FOR UPDATE');$st->execute([$id]);$old=$st->fetchColumn();if($old===false)throw new RuntimeException('Pengajuan tidak ditemukan.');$note=aw_post('notes',4000);$db->prepare('UPDATE aw_applications SET status=?,staff_notes=? WHERE id=?')->execute([$status,$note,$id]);$db->prepare('INSERT INTO aw_history(application_id,previous_status,new_status,actor_id,notes) VALUES (?,?,?,?,?)')->execute([$id,$old,$status,$user['id'],$note]);$db->commit();try {require_once dirname(__DIR__).'/mobile-api/bootstrap.php';$recipient=$db->prepare('SELECT account_id FROM aw_applications WHERE id=?');$recipient->execute([$id]);mobile_emit('progres_surat','Progres Ahli Waris: '.ucfirst($status),'Periksa status permohonan di Portal Warga','personal',$recipient->fetchColumn()?:null);}catch(Throwable $eventEx){error_log($eventEx->getMessage());}$ok='Status berhasil disimpan.';}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();$err=$e->getMessage();}
$db=aw_db();$q=$db->query('SELECT id,reference_no,applicant_name,applicant_phone,deceased_name,status,created_at,staff_notes FROM aw_applications ORDER BY created_at DESC LIMIT 200');$rows=$q->fetchAll();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Ahli Waris</title><link rel="stylesheet" href="style.css"><style>table{min-width:860px}form.inline{display:flex;gap:7px;flex-wrap:wrap}select{width:auto;min-width:120px}.btn{background:#08664a;color:#fff;border:0;border-radius:8px;padding:8px;cursor:pointer}</style><?php if(isset($_GET['embedded'])): ?><style>html,body{background:#f3f7fc!important;margin:0}.wrap{max-width:none!important;width:100%!important;padding:16px!important}.hero{padding:12px 16px!important;margin-bottom:12px!important;border-radius:14px!important}.hero h1{font-size:21px!important;font-family:inherit!important;margin:0 0 5px!important}.hero p{font-size:13px!important;margin:0}.panel{padding:12px!important}.table-wrap{overflow:auto}td,th{padding:10px!important;font-size:13px!important}input,select{font-size:13px!important}</style><?php endif; ?></head><body><main class="wrap"><header class="hero"><h1>Verifikasi Permohonan Ahli Waris</h1><p>Daftar pengajuan, status, catatan dan lampiran.</p></header><?php if($err):?><div class="alert error"><?=aw_e($err)?></div><?php endif;?><?php if($ok):?><div class="alert ok"><?=aw_e($ok)?></div><?php endif;?><section class="panel"><div class="table-wrap"><table><thead><tr><th>Nomor / Tanggal</th><th>Pemohon</th><th>Pewaris</th><th>Dokumen</th><th>Status & Tindakan</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=aw_e($r['reference_no'])?></b><div><?=aw_e($r['created_at'])?></div></td><td><?=aw_e($r['applicant_name'])?><div><?=aw_e($r['applicant_phone'])?></div></td><td><?=aw_e($r['deceased_name'])?></td><td><a href="detail.php?id=<?=$r['id']?>">Detail / Lampiran</a></td><td><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=aw_e(aw_csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach($allowed as $s):?><option value="<?=$s?>" <?=$s===$r['status']?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select><input type="text" name="notes" placeholder="Catatan petugas" value="<?=aw_e($r['staff_notes'])?>"><button class="btn">Simpan</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">Belum ada pengajuan.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>